## RecyclerView Implementation

- **ViewHolder Pattern**: Reuses view objects to avoid expensive findViewById calls
- **DiffUtil**: Calculates differences between old and new lists for efficient updates
- **Layout Manager**: Manages item positioning (LinearLayoutManager for lists)

```kotlin
class ProfileAdapter : ListAdapter<Profile, ProfileAdapter.ViewHolder>(DiffCallback()) {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_profile, parent, false)
        return ViewHolder(view)
    }

    override fun onBindViewHolder(holder: ViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    class ViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        fun bind(profile: Profile) {
            // Bind profile data to views
        }
    }

    class DiffCallback : DiffUtil.ItemCallback<Profile>() {
        override fun areItemsTheSame(oldItem: Profile, newItem: Profile): Boolean =
            oldItem.id == newItem.id

        override fun areContentsTheSame(oldItem: Profile, newItem: Profile): Boolean =
            oldItem == newItem
    }
}
```

